// Normalize Issue — the single entry point for Stage 2.
//
// The GitHub node polls `repository:getIssues`, so each item.json is a FLAT
// GitHub issue object: no webhook envelope, no repository block. That means the
// repo coordinates simply are not in the payload — the poller credential/node is
// pinned to one repo, so we pin the same one here.
const OWNER = 'oneshotmn';
const REPO = 'oneshotmn';

// The labels ARE the state machine. 'ready' is the only way a human hands an
// issue to the pipeline, and 'plan-proposed' is the marker the pipeline writes
// back when it has already answered.
//
// 'plan-proposed' is deliberately NOT a reason to skip. It records that a plan
// was posted, not which revision of the issue it was written against; skipping
// on it would freeze a stale plan on any ticket Brian edits after the fact. The
// content-hash replay guard downstream is what makes the unchanged case free.
//
// What DOES stop this stage is the human gate. Once 'approved' is applied the
// issue is Stage 3's, and rewriting its plan comment mid-build is the accident
// this list prevents; 'pr-open' and 'shipped' say the same thing later.
const INPUT_LABEL = 'ready';
const PAST_GATE_LABELS = ["approved","pr-open","shipped"];

// FNV-1a, 32-bit. Deliberately not crypto: it must be pure, dependency-free
// (n8n Code nodes have no npm), and identical on every run, because it is the
// only thing standing between us and duplicate plan comments.
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    // h * 16777619 with 32-bit overflow, via shifts so we stay inside int32.
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

// GitHub normally sends label objects, but hand-built fixtures and some API
// shapes hand back bare strings. Tolerate both rather than crashing the poll.
function labelName(label) {
  if (typeof label === 'string') return label;
  return label && typeof label.name === 'string' ? label.name : '';
}

const out = [];

for (const item of $input.all()) {
  const issue = item.json || {};
  const user = issue.user || {};

  const title = typeof issue.title === 'string' ? issue.title : '';
  const body = typeof issue.body === 'string' ? issue.body : '';
  const author = typeof user.login === 'string' ? user.login : '';
  const labels = (Array.isArray(issue.labels) ? issue.labels : [])
    .map(labelName)
    .filter(Boolean);

  // Hash the CONTENT a plan is derived from — title + body. Anything that would
  // change the plan changes the hash; anything that would not (a re-poll, a
  // label churn, a new updated_at) leaves it alone.
  const contentHash = fnv1a(title + '\n' + body);

  // Content-keyed, never Date.now()-keyed. Two consequences we actually want:
  // replaying the same poll is free (identical key -> downstream dedupe drops
  // it), and editing the issue mints a new key so the pipeline re-plans against
  // the text the human just fixed.
  const idempotencyKey = OWNER + '/' + REPO + '#' + issue.number + '@' + contentHash;

  const reasons = [];
  if (!labels.includes(INPUT_LABEL)) {
    reasons.push('issue is not labelled ' + INPUT_LABEL);
  }
  // The human gate is the hard stop. 'plan-proposed' is deliberately absent from
  // this list: an issue that already carries it is still admitted,
  // and the content-hash replay guard downstream decides whether the plan on it
  // is stale. Skipping here instead would make an edited ticket unanswerable.
  const pastGate = labels.filter((l) => PAST_GATE_LABELS.includes(l));
  if (pastGate.length > 0) {
    reasons.push(
      'issue carries ' + pastGate.join(', ') + '; it is past the human gate and belongs to a later stage',
    );
  }
  // Bot exclusion is the loop-breaker. This pipeline's own plan comment (and any
  // label it sets) arrives back through the same poll; if a bot-authored issue
  // could pass, the pipeline would answer itself forever.
  if (user.type === 'Bot' || /\[bot\]$/.test(author)) {
    reasons.push('author ' + (author || 'unknown') + ' is a bot');
  }
  if (issue.state !== 'open') {
    reasons.push('issue state is ' + (issue.state || 'unknown') + ', not open');
  }
  if (!issue.number) {
    reasons.push('issue has no number');
  }

  out.push({
    json: {
      owner: OWNER,
      repo: REPO,
      issueNumber: issue.number,
      issueTitle: title,
      issueBody: body,
      issueUrl: issue.html_url,
      author: author,
      labels: labels,
      updatedAt: issue.updated_at,
      contentHash: contentHash,
      idempotencyKey: idempotencyKey,
      // Observability only — deliberately NOT part of idempotencyKey.
      receivedAt: new Date().toISOString(),
      shouldPlan: reasons.length === 0,
      skipReason: reasons.join('; '),
    },
  });
}

return out;

// Resolve Plan State — the replay guard, deliberately upstream of the model.
//
// Two cheap GitHub reads decide whether the expensive call happens at all:
// `Find Plan Comment` lists the thread, and this node scans it for OUR sticky.
// A guard downstream of Opus could only stop a duplicate comment; it could never
// refund the Opus call, and on a polled trigger the "nothing changed" path is
// the one we walk most often.

// The sentinel identifies the pipeline's own plan comment. Stage 1 posts its
// scenario comment under a DIFFERENT sentinel, so an exact substring match is
// what keeps the two stages from reading each other's stickies.
const SENTINEL = '<!-- oneshot-pipeline: implementation-plan -->';
// The key line records WHICH content revision that plan was written against.
const KEY_RE = /<!-- oneshot-pipeline-plan-key:\s*(.*?)\s*-->/;

// The envelope is the source of truth for the issue; the HTTP node's output is
// only the comment thread. Read them from their own nodes rather than hoping
// they got merged into one item.
const src = $('Normalize Issue').first().json || {};
const res = $input.first().json || {};

// fullResponse:true wraps the array in { statusCode, body }. Tolerate a bare
// array too (fullResponse off, or a hand-built fixture), and tolerate NEITHER:
// `Find Plan Comment` sets alwaysOutputData, so an issue with an empty thread
// arrives here as a single empty item. That branch is the FIRST EVER plan — the
// exact case this pipeline exists for — so it must resolve to "no sticky", not
// crash and not silently drop the item.
const comments = Array.isArray(res.body) ? res.body : Array.isArray(res) ? res : [];

let stickyCommentId = null;
let stickyKey = '';
// LAST match wins. If a duplicate sticky ever got posted, the newest one is the
// one a rewrite should target, so the guard converges instead of ping-ponging
// between two comments forever.
for (const c of comments) {
  const body = c && typeof c.body === 'string' ? c.body : '';
  if (!body.includes(SENTINEL)) continue;
  stickyCommentId = c.id === undefined ? null : c.id;
  const m = KEY_RE.exec(body);
  stickyKey = m && typeof m[1] === 'string' ? m[1] : '';
}

const stickyExists = stickyCommentId !== null;

// FAIL OPEN. Every clause below is a reason to believe the key is trustworthy;
// if ANY of them is missing — no content hash, no sticky, a sticky posted by an
// older format with no key line — we plan again rather than skip. One duplicate
// plan comment is cheap and visible; an issue that can never be planned because
// an unreadable key looked like a match is neither.
const isReplay =
  typeof src.contentHash === 'string' &&
  src.contentHash !== '' &&
  stickyExists &&
  stickyKey !== '' &&
  stickyKey === src.idempotencyKey;

const replayReason = isReplay
  ? 'plan comment ' + stickyCommentId + ' already carries key ' + stickyKey +
    '; issue content is unchanged, so the model call is skipped'
  : '';

// Exactly one item out: the envelope, widened with the sticky verdict. Later
// slices branch on isReplay and rewrite stickyCommentId in place.
return [
  {
    json: {
      ...src,
      commentCount: comments.length,
      stickyCommentId: stickyCommentId,
      stickyKey: stickyKey,
      stickyExists: stickyExists,
      isReplay: isReplay,
      replayReason: replayReason,
    },
  },
];

// Render Plan Comment — turn the model's structured plan into the sticky comment.
//
// HARD RULE 1: never emit 'Closes #N' or 'Fixes #N'. Ticket<->PR linking belongs
// to Stage 3. A Closes line in a plain comment claims a ticket without taking
// it — GitHub would auto-close the issue on the next unrelated merge from this
// branch, and nothing in this stage has written a line of code yet.
//
// HARD RULE 2: never mention a triage label other than \`approved\`. The labels
// ARE Brian's state machine; a comment that name-drops 'ready' or 'needs-info'
// teaches readers a transition this stage has no authority to perform.

const src = $('Resolve Plan State').first().json || {};
const j = ($input.first() || {}).json || {};

// chainLlm with a structured parser lands the object on .output. Without a
// parser it lands on .text, and some builds use .response — and any of the three
// can arrive as a JSON STRING rather than a parsed object. Tolerate every shape:
// the alternative is throwing away a perfectly good (already paid for) model
// call because the field name moved.
function asObject(v) {
  if (!v) return null;
  if (typeof v === 'string') {
    try {
      const parsed = JSON.parse(v);
      return parsed && typeof parsed === 'object' ? parsed : null;
    } catch (err) {
      return null;
    }
  }
  return typeof v === 'object' ? v : null;
}

const plan = asObject(j.output) || asObject(j.text) || asObject(j.response) || {};

function str(v) {
  return typeof v === 'string' ? v.trim() : '';
}
function list(v) {
  return (Array.isArray(v) ? v : []).map(str).filter(Boolean);
}

const summary = str(plan.summary);
const testApproach = str(plan.test_approach);
const risks = list(plan.risks);
const openQuestions = list(plan.open_questions);
const steps = (Array.isArray(plan.steps) ? plan.steps : [])
  .map(function (s) {
    return { title: str(s && s.title), files: list(s && s.files), test: str(s && s.test) };
  })
  .filter(function (s) {
    return s.title || s.test || s.files.length;
  });

// Refuse loudly rather than post a hollow comment. A comment carrying the
// sentinel and the key line but no plan is WORSE than no comment at all: the
// replay guard reads that key back on the next poll, rules "already planned",
// and the issue is locked out of the pipeline forever. A failed execution is
// visible in n8n and re-runs on the next poll; a hollow sticky is neither.
if (!summary && steps.length === 0) {
  throw new Error(
    'refusing to post a hollow plan comment: the model returned no summary and no steps for ' +
      src.idempotencyKey,
  );
}

// Union the top-level files with every path the individual steps name, keeping
// first-seen order. The model routinely lists a file in a step and forgets it at
// the top level, and "files to touch" is the section a reviewer actually scans.
const stepFiles = steps.reduce(function (acc, s) {
  return acc.concat(s.files);
}, []);
const files = [];
for (const f of list(plan.files).concat(stepFiles)) {
  if (files.indexOf(f) === -1) files.push(f);
}

const L = [];
// Line 1 is the sentinel the replay guard greps for; line 2 records WHICH
// revision of the issue this plan was written against. Both must stay on their
// own line and stay first — the guard's regex reads them back verbatim.
L.push('<!-- oneshot-pipeline: implementation-plan -->');
L.push('<!-- oneshot-pipeline-plan-key: ' + src.idempotencyKey + ' -->');
L.push('');
L.push(
  '**This is a proposed plan, not work that happened.** Nothing has been implemented: no branch, no code, no pull request.',
);
L.push('');
L.push('## Summary');
L.push('');
L.push(summary || '_The model returned steps but no one-line summary._');
L.push('');
L.push('## Files to touch');
L.push('');
if (files.length) {
  for (const f of files) L.push('- \`' + f + '\`');
} else {
  L.push('_No paths named yet — see the open questions below._');
}
L.push('');
L.push('## Plan');
L.push('');
steps.forEach(function (s, i) {
  L.push(i + 1 + '. **' + (s.title || 'step ' + (i + 1)) + '**');
  if (s.files.length) {
    L.push(
      '   - files: ' +
        s.files
          .map(function (f) {
            return '\`' + f + '\`';
          })
          .join(', '),
    );
  }
  if (s.test) L.push('   - test: ' + s.test);
});
if (!steps.length) L.push('_No step breakdown returned._');
L.push('');
L.push('## Test approach');
L.push('');
L.push(testApproach || '_Not stated by the model — worth asking before approving._');
// Risks and open questions are omitted when empty. An empty section under a
// heading reads as "we checked and there are none", which is a stronger claim
// than the model actually made.
if (risks.length) {
  L.push('');
  L.push('## Risks');
  L.push('');
  for (const r of risks) L.push('- ' + r);
}
if (openQuestions.length) {
  L.push('');
  L.push('## Open questions');
  L.push('');
  for (const q of openQuestions) L.push('- ' + q);
}
L.push('');
L.push('---');
L.push('');
// The gate paragraph. This stage stops here on purpose: it applies
// 'plan-proposed' and waits. A human moves it forward, and this is where they
// find out how.
L.push(
  'This plan is waiting on a human. If it is right, apply the \`approved\` label to this issue to hand it to the build stage. Nothing else happens until then — this stage will not apply that label itself, and it will not write any code on its own.',
);

const comment = L.join('\n');

return [
  {
    json: {
      owner: src.owner,
      repo: src.repo,
      issueNumber: src.issueNumber,
      issueUrl: src.issueUrl,
      idempotencyKey: src.idempotencyKey,
      // Carried forward so the write branch can pick PATCH-in-place vs create,
      // and so the terminal audit record can say which one actually ran.
      stickyExists: src.stickyExists,
      stickyCommentId: src.stickyCommentId,
      planChars: comment.length,
      comment: comment,
    },
  },
];

// Plan Gate Handle — terminal node, emits the audit record for this run.
//
// Nothing consumes this inside n8n; it exists so an execution in the log answers
// "what did the pipeline do to this issue, and under which content revision"
// without anyone re-reading the GitHub thread.
//
// The write branch is read from 'Render Plan Comment', not from $input: the two
// upstream write nodes (HTTP PATCH vs the GitHub node) emit completely different
// shapes, and the render node is the last point where one known shape existed.
const src = $('Render Plan Comment').first().json || {};

return [
  {
    json: {
      gate: 'plan-approval',
      repo_full: src.owner + '/' + src.repo,
      issue_number: src.issueNumber,
      action: src.stickyExists ? 'updated' : 'created',
      idempotency_key: src.idempotencyKey,
      // Recorded as a constant, not read back from the API response: this is a
      // statement about what this workflow is allowed to write. 'approved' is
      // never in this field, because the workflow must never apply it.
      label_applied: 'plan-proposed',
      comment_chars: src.planChars,
    },
  },
];
